/**
 * Tutorials data for TEMOTO framework
 * Each tutorial has:
 * - title: The name of the tutorial
 * - description: Brief overview of what the tutorial covers
 * - level: Difficulty level (Beginner, Intermediate, Advanced)
 * - link: URL to the tutorial page
 */

const tutorials = [
    {
      title: "Getting Started with TEMOTO",
      description: "Learn how to install TEMOTO and set up your first project. This tutorial covers the basic concepts and architecture of the framework.",
      level: "Beginner",
      link: "https://github.com/temoto-framework/temoto/wiki"
    },
    {
      title: "Creating Your First Robot Task",
      description: "Step-by-step guide to defining and executing a simple robotic task using TEMOTO's task execution engine.",
      level: "Beginner",
      link: "https://github.com/temoto-framework/tutorials/first-robot-task"
    },
    {
      title: "Human-Robot Interaction Basics",
      description: "Introduction to using TEMOTO's Human-Robot Interaction (HRI) components to enable natural communication with robots.",
      level: "Beginner",
      link: "https://github.com/temoto-framework/tutorials/hri-basics"
    },
    {
      title: "Task Planning and Scheduling",
      description: "Learn how to create complex multi-step task plans and schedules for robotic operations with error handling.",
      level: "Intermediate",
      link: "https://github.com/temoto-framework/tutorials/task-planning"
    },
    {
      title: "Sensor Integration and Perception",
      description: "Guide to integrating various sensors with TEMOTO and using perception modules for environment understanding.",
      level: "Intermediate",
      link: "https://github.com/temoto-framework/tutorials/sensor-integration"
    },
    {
      title: "Error Recovery Strategies",
      description: "Implement robust error detection and recovery mechanisms to handle unexpected situations during task execution.",
      level: "Intermediate",
      link: "https://github.com/temoto-framework/tutorials/error-recovery"
    },
    {
      title: "Custom Action Development",
      description: "Create your own custom robot actions and behaviors by extending TEMOTO's action library.",
      level: "Advanced",
      link: "https://github.com/temoto-framework/tutorials/custom-actions"
    },
    {
      title: "Multi-Robot Coordination",
      description: "Advanced techniques for coordinating multiple robots to work together on complex tasks.",
      level: "Advanced",
      link: "https://github.com/temoto-framework/tutorials/multi-robot"
    },
    {
      title: "Natural Language Processing for Robotics",
      description: "Integrate advanced NLP capabilities into your robot's interaction system using TEMOTO's language processing modules.",
      level: "Advanced",
      link: "https://github.com/temoto-framework/tutorials/nlp-robotics"
    }
  ];

  export default tutorials;
